solution.solution.cpp:
#include <cctype>
#include <optional>
#include <string>
#include <utility>
#include <vector>

struct Url { std::string scheme, host; int port; std::string path, query, fragment; };

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

std::optional<Url> parseUrl(const std::string& text)
{
    const std::size_t sep{ text.find("://") };
    if (sep == std::string::npos || sep == 0) return std::nullopt;
    Url u{};
    u.scheme = lower(text.substr(0, sep));
    if (!std::isalpha(static_cast<unsigned char>(u.scheme[0]))) return std::nullopt;
    for (char c : u.scheme) if (!std::isalnum(static_cast<unsigned char>(c)) && c != '+' && c != '-' && c != '.') return std::nullopt;
    std::string rest{ text.substr(sep + 3) };
    if (const std::size_t hash{ rest.find('#') }; hash != std::string::npos) { u.fragment = rest.substr(hash + 1); rest.erase(hash); }
    if (const std::size_t q{ rest.find('?') }; q != std::string::npos) { u.query = rest.substr(q + 1); rest.erase(q); }
    const std::size_t slash{ rest.find('/') };
    std::string authority{ rest.substr(0, slash) };
    u.path = slash == std::string::npos ? "/" : rest.substr(slash);
    std::string portText;
    if (!authority.empty() && authority[0] == '[')
    {
        const std::size_t close{ authority.find(']') };
        if (close == std::string::npos) return std::nullopt;
        u.host = authority.substr(1, close - 1);
        const std::string after{ authority.substr(close + 1) };
        if (!after.empty()) { if (after[0] != ':') return std::nullopt; portText = after.substr(1); if (portText.empty()) return std::nullopt; }
    }
    else
    {
        const std::size_t colon{ authority.find(':') };
        u.host = authority.substr(0, colon);
        if (colon != std::string::npos) { portText = authority.substr(colon + 1); if (portText.empty()) return std::nullopt; }
    }
    if (u.host.empty()) return std::nullopt;
    u.host = lower(u.host);
    if (!portText.empty())
    {
        if (portText.size() > 5) return std::nullopt;
        for (char c : portText) if (!std::isdigit(static_cast<unsigned char>(c))) return std::nullopt;
        u.port = std::stoi(portText);
        if (u.port < 1 || u.port > 65535) return std::nullopt;
    }
    else u.port = u.scheme == "http" ? 80 : u.scheme == "https" ? 443 : 0;
    return u;
}

std::string percentEncode(const std::string& text)
{
    static const char* const HEX{ "0123456789ABCDEF" };
    std::string out;
    for (unsigned char c : text)
    {
        if (std::isalnum(c) || c == '-' || c == '.' || c == '_' || c == '~') out += static_cast<char>(c);
        else { out += '%'; out += HEX[c >> 4]; out += HEX[c & 0xF]; }
    }
    return out;
}

static int hexValue(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

std::optional<std::string> percentDecode(const std::string& text)
{
    std::string out;
    for (std::size_t i{ 0 }; i < text.size(); ++i)
    {
        if (text[i] != '%') { out += text[i]; continue; }
        if (i + 2 >= text.size()) return std::nullopt;
        const int hi{ hexValue(text[i + 1]) }, lo{ hexValue(text[i + 2]) };
        if (hi < 0 || lo < 0) return std::nullopt;
        out += static_cast<char>(hi * 16 + lo);
        i += 2;
    }
    return out;
}

std::vector<std::pair<std::string, std::string>> parseQuery(const std::string& query)
{
    std::vector<std::pair<std::string, std::string>> out;
    std::size_t start{ 0 };
    while (start <= query.size())
    {
        const std::size_t amp{ query.find('&', start) };
        std::string piece{ query.substr(start, amp == std::string::npos ? std::string::npos : amp - start) };
        if (!piece.empty())
        {
            for (char& c : piece) if (c == '+') c = ' ';
            const std::size_t eq{ piece.find('=') };
            const auto name{ percentDecode(piece.substr(0, eq)) };
            const auto value{ percentDecode(eq == std::string::npos ? "" : piece.substr(eq + 1)) };
            if (name && value) out.push_back({ *name, *value });
        }
        if (amp == std::string::npos) break;
        start = amp + 1;
    }
    return out;
}

unitTests:
using Pairs = std::vector<std::pair<std::string, std::string>>;
TEST("full URLs") {
    const auto u{ parseUrl("HTTPS://Xenon.JustLoofy.dev:8443/courses/net%20working?tab=lessons&sort=new#part-2") };
    CHECK(u.has_value());
    if (!u) return;
    CHECK_EQ(u->scheme, std::string("https"));
    CHECK_EQ(u->host, std::string("xenon.justloofy.dev"));
    CHECK_EQ(u->port, 8443);
    CHECK_EQ(u->path, std::string("/courses/net%20working"));
    CHECK_EQ(u->query, std::string("tab=lessons&sort=new"));
    CHECK_EQ(u->fragment, std::string("part-2"));
}
TEST("defaults and IPv6") {
    const auto a{ parseUrl("http://example.com") };
    if (a) { CHECK_EQ(a->port, 80); CHECK_EQ(a->path, std::string("/")); }
    CHECK(a.has_value());
    const auto b{ parseUrl("https://[::1]:9000/x") };
    if (b) { CHECK_EQ(b->host, std::string("::1")); CHECK_EQ(b->port, 9000); }
    CHECK(b.has_value());
    const auto c{ parseUrl("ftp://files.example.com/pub") };
    if (c) CHECK_EQ(c->port, 0);
    for (const char* bad : { "example.com/x", "http://", "http://:80/", "http://host:0/", "http://host:99999/", "http://host:8a/", "1http://x" })
        CHECK(!parseUrl(bad).has_value());
}
TEST("percent-encoding") {
    CHECK_EQ(percentEncode("net working/é"), std::string("net%20working%2F%C3%A9"));
    CHECK_EQ(percentEncode("A-z_0.9~"), std::string("A-z_0.9~"));
    CHECK_EQ(percentDecode("net%20working%2f%C3%A9").value_or("?"), std::string("net working/\xC3\xA9"));
    CHECK(!percentDecode("bad%2").has_value());
    CHECK(!percentDecode("bad%zz").has_value());
    CHECK(!percentDecode("%").has_value());
    CHECK_EQ(percentDecode(percentEncode("a+b=c&d")).value_or("?"), std::string("a+b=c&d"));
}
TEST("query strings") {
    CHECK(parseQuery("q=networking+basics&level=2&tag=c%2B%2B") == (Pairs{ { "q", "networking basics" }, { "level", "2" }, { "tag", "c++" } }));
    CHECK(parseQuery("a&&b=&=x&tag=1&tag=2") == (Pairs{ { "a", "" }, { "b", "" }, { "", "x" }, { "tag", "1" }, { "tag", "2" } }));
    CHECK(parseQuery("bad=%G1&ok=1") == (Pairs{ { "ok", "1" } }));
    CHECK(parseQuery("").empty());
}

